recipes.code:
{
  "inputs": [
    {
      "id": "database-url",
      "type": "promptString",
      "description": "Database connection string. PostgreSQL, MySQL, SQLite, CockroachDB, or a ClickHouse HTTP URL.",
      "password": true
    }
  ],
  "servers": {
    "mcp": {
      "type": "stdio",
      "command": "npx",
      "args": [
        "-y",
        "@valv/mcp@0.6.2"
      ],
      "env": {
        "DATABASE_URL": "${input:database-url}",
        "VALV_PROVIDER": "<valv-provider>",
        "VALV_DATABASE": "<valv-database>",
        "VALV_TABLES": "<valv-tables>",
        "VALV_EXCLUDE": "<valv-exclude>",
        "VALV_POLICY_FILE": "/absolute/path/to/target",
        "VALV_CONTEXT": "<valv-context>",
        "VALV_HTTP_PORT": "<valv-http-port>"
      }
    }
  }
}
